function main(): void {
    const absent: { a?: string | null } = {};
    const present: { a?: string | null } = { a: undefined };
    const nullable: { a?: string | null } = { a: null };
    assert(absent.a === undefined, "omitted property reads undefined");
    assert(!Object.hasOwn(absent, "a"), "omitted property is absent");
    assert(Object.hasOwn(present, "a"), "explicit undefined is present");
    assert(Object.hasOwn(nullable, "a"), "explicit null is present");
    assert(Object.keys(present).length === 1, "undefined key enumerates");
    assert(Object.values(present)[0] === undefined, "undefined value enumerates");
    const copied = { ...present };
    assert(Object.hasOwn(copied, "a"), "spread retains explicit undefined");
    assert(copied.a === undefined, "spread retains undefined value");
    absent.a = undefined;
    assert(Object.hasOwn(absent, "a"), "assignment marks undefined present");
    const dictionary: { [key: string]: string } = {};
    assert(dictionary["missing"] === undefined, "dictionary miss");
    assert(String(undefined) === "undefined", "undefined string conversion");
    assert(Number.isNaN(Number(undefined)), "undefined numeric conversion");
    assert(!!undefined === false, "undefined boolean conversion");
    assert(!Object.is(null, undefined), "null differs from undefined");
    assert(Object.is(undefined, undefined), "undefined equals itself");
    assert(Object.is(undefined), "omitted comparison argument is undefined");
    assert(Object.is(), "both omitted comparison arguments are undefined");
    assert(!Error.isError(undefined), "undefined is not an error");
    assert(!Error.isError(), "omitted argument is not an error");
    assert(JSON.stringify(present) === "{}", "JSON omits undefined property");
    assert(JSON.stringify(nullable) === '{"a":null}', "JSON retains null property");
    const nullishValues: unknown[] = [undefined, null];
    assert(JSON.stringify(nullishValues) === "[null,null]", "JSON array nullish values");
    const nested = { data: [present, nullable], omitted: undefined };
    assert(JSON.stringify(nested) === '{"data":[{},{"a":null}]}', "JSON nested contexts");
    assert(JSON.stringify(undefined) === undefined, "top-level undefined produces no text");
    const completed = [1].values();
    assert(!completed.next().done, "iterator yields");
    const end = completed.next();
    assert(end.done, "iterator completes");
    assert(end.value === undefined, "iterator completion value");
}
